INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data)
VALUES ('协创数据', '300857.SZ', 'semiconductor', 'terminal', true, NULL, 1237.6, NULL, 126.41, NULL, '{"name":"协创数据","code":"300857.SZ","industry":"semiconductor","seg":"terminal","market":"CN","listed":true,"cap":1237.6,"pe":49.34,"rev":126.41,"revGrowth":155.7,"gross":25.15,"rd":3.4,"desc":"协创数据技术股份有限公司（2005-11-18 成立，2020-07-27 创业板上市），总部深圳福田，主营「智能算力产品及服务 + 数据存储设备 + 服务器及周边再制造 + AIoT 智能终端」四大板块，并已升级为「智能终端 + 云算力 + 光器件」全链路协同架构。算力端已具备万卡级集群规划建设与运营能力，自研 FCloud 训推融合平台实现 GPU 资源池化、异构算力纳管与多租户调度；存储端以 SSD、内存条、NAS 及服务器存储设备为主，向企业级与高性能存储升级；再制造端覆盖回收、无损拆解、故障检测、维修升级到整机装配与老化测试全流程；AIoT 端为智能摄像机、门铃、智能家居等硬件。2026 年 4 月以 5.10 亿元增资控股光为科技 51% 股权（5 月完成工商变更并表），切入高速光芯片与光模块，形成「算—连—存」三位一体布局。同时以 OmniBot（具身智能）、Rimo（智慧零售）、BioViMo（生物医药）、TokenShare（企业级模型服务）延伸应用层。2026H1 营收 125.23-126.41 亿元（+153%~156%）、归母净利 18.38-18.63 亿元（+325%~331%），服务器及周边再制造营收 34.47 亿元（+313%）增速最快；乌兰察布一期 2.3 万 P 算力集群在建。","latestTech":"2026-04 以 5.10 亿元增资控股国家级专精特新「小巨人」光为科技 51%，布局 200G/400G/800G/1.6T 全系列光模块与 LPO、NPO-Pro 技术路线；自研 FCloud 训推融合平台上线；规划乌兰察布一期 2.3 万 P 算力集群","tech":[{"date":"2026-09","title":"子公司光为科技联合提出 NPO（近封装光学）行业标准，深度参与超节点光互联标准制定"},{"date":"2026-05","title":"完成对光为科技的工商变更登记，正式纳入合并报表范围；光为科技 400G 光模块功耗低至 2.4W（行业平均约 8W），技术团队由原 Finisar 首席科学家、100G 光模块发明人宋云鹏博士领衔"},{"date":"2026-04","title":"以 5.10 亿元增资控股光为科技 51% 股权，业务由「终端制造」升级为「核心器件 + 终端 + 服务」；光为科技为国家级专精特新「小巨人」，是国家级最高性能超算中心的单一采购来源供应商"},{"date":"2026","title":"自研 FCloud 训推融合平台实现 GPU 资源池化管理、任务调度、模型训练与部署全流程；形成万卡级集群的规划建设、网络组网与运营管理能力"},{"date":"2026","title":"规划建设乌兰察布一期 2.3 万 P 算力集群，按计划推进建设、交付与验收；围绕 OmniBot、Rimo、BioViMo、TokenShare 布局行业应用"}],"executives":[{"name":"耿康铭","title":"董事长","role":"board","tenure":"2025.6–2028.6","shares":"108.9 万元薪酬","bio":"男，52 岁，硕士。2025 年 6 月 30 日经第四届董事会第一次会议选举为董事长，并任董事会审计委员会委员。主导公司从智能终端制造向「智能算力 + 光器件」全栈 AI 基础设施的战略升级。"},{"name":"林坤煌","title":"副董事长","role":"board","tenure":"2025.6–2028.6","bio":"男，63 岁，本科。第四届董事会副董事长。"},{"name":"潘文俊","title":"总经理、法定代表人","role":"management","tenure":"2025.6–2028.6","shares":"104.18 万股","bio":"男，47 岁，本科。公司法定代表人兼总经理，2026 年 5 月通过竞价交易减持 31.22 万股；薪酬 78.29 万元。"},{"name":"甘杏","title":"副总经理、董事会秘书","role":"management","tenure":"2025.6–2028.6","shares":"13.89 万股","bio":"女，42 岁，本科。分管投资者关系与信息披露，薪酬 39.04 万元。"},{"name":"易洲","title":"副总经理","role":"management","tenure":"2025.6–2028.6","shares":"69.45 万股","bio":"男，46 岁，大专。薪酬 78.29 万元。"},{"name":"陈礼平","title":"副总经理","role":"management","tenure":"2025.6–2028.6","shares":"37.85 万股","bio":"男，45 岁，本科。薪酬 57.40 万元。"},{"name":"瞿亚能","title":"财务负责人","role":"management","tenure":"2025.6–2028.6","shares":"6.17 万股","bio":"男，38 岁，本科。薪酬 33.57 万元。"},{"name":"陈亚伟","title":"职工代表董事","role":"board","tenure":"2025.6–2028.6","shares":"23.20 万股","bio":"女，40 岁，本科。由职工代表大会选举产生，薪酬 57.28 万元。"},{"name":"李平","title":"独立董事","role":"board","tenure":"2025.6–2028.6","bio":"男，53 岁，硕士。第四届董事会独立董事，任审计委员会委员。"},{"name":"黄福平","title":"独立董事","role":"board","tenure":"2025.6–2028.6","bio":"男，58 岁，硕士。第四届董事会独立董事，任审计委员会主任委员。"},{"name":"林祥","title":"独立董事","role":"board","tenure":"2025.6–2028.6","bio":"男，41 岁，本科。第四届董事会独立董事。"}],"funding":[],"note":"协创数据是「存储 + 算力 + 光互连」跨界整合的代表：传统主业数据存储设备（SSD、内存条、NAS）属半导体下游应用，2026 年通过控股光为科技向上游切入光芯片与光模块。产业链定位上，其算力服务与光互连业务归入终端「数据中心 / 智算」，存储设备业务与 design 域「存储模组与主控」的江波龙、佰维存储同属存储下游。与工业富联（服务器代工）、浪潮信息（服务器整机）相比，协创数据的差异化在于「算力运营 + 光器件自供 + 再制造循环」的组合，光为科技 400G 光模块功耗 2.4W 显著低于行业平均 8W，是其核心竞争力。风险点：算力租赁业务实际上架率与在手订单周期未充分披露，市场存在分歧；光模块业务尚处产能爬坡期。"}'::jsonb)
