INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data)
VALUES ('思敏威', NULL, 'semiconductor', 'design', false, '天使轮', NULL, NULL, NULL, '2026-10', '{"name":"思敏威","industry":"semiconductor","seg":"design","listed":false,"round":"天使轮","valuation":null,"lastFunding":"2026-10","desc":"思敏威（上海）集成电路有限公司（CiMicro.Ai），2024 年 12 月成立于上海浦东张江，3D 存算一体 AI 推理芯片设计公司。采用「3D 堆叠近存计算 + SRAM 存内计算 + 自研 RISC-V 计算核心 + Chiplet 芯粒互联」融合架构，核心产品为青衡 3D-HPU（存算融合架构）与 3D-cHMC（3D-computing Hyper Memory Cube，3D 算力超存立方）基座，面向大模型推理与端侧 AI 场景，目标把推理能效提升一个数量级。创始团队来自英特尔、AMD、华为海思，核心成员平均 20 年以上 SoC 设计经验、10 年以上存算一体积累，累计流片 20 余次；2025 年率先完成 FP4 浮点存内计算核心 IP 验证，近五年在 ISSCC / JSSC 发表论文 11 篇。","latestTech":"2026 年推进青衡 3D-HPU 系列产品化，与领开半导体达成 3D 堆叠存算融合 + HBF+ 战略合作，切入高带宽存储近存计算路线","tech":[{"date":"2026-06","title":"与领开半导体（东方富海系）达成战略合作，围绕 3D 堆叠存算融合架构与 HBF+（高带宽闪存）技术路线共同开发"},{"date":"2026","title":"与无问芯穹建立商业合作，存算一体推理方案接入其异构算力与推理引擎生态"},{"date":"2025","title":"率先完成 FP4 浮点存内计算核心 IP 验证，成为国内少数打通低精度浮点存内计算链路的团队"},{"date":"2024-12","title":"公司于上海浦东张江注册成立，确定 3D 存算一体 AI 推理芯片方向"}],"executives":[{"name":"李明","title":"法定代表人","role":"management","bio":"思敏威（上海）集成电路有限公司法定代表人。公司由具备英特尔、AMD、华为海思背景的 SoC 与存算一体团队创立，核心成员平均拥有 20 年以上芯片设计经验、10 年以上存算一体技术积累，累计完成 20 余次流片，近五年在 ISSCC、JSSC 等集成电路顶级会议与期刊发表论文 11 篇。技术路线覆盖 SRAM 存内计算、3D 异质封装近存计算、RISC-V 计算核心与 Chiplet 芯粒互联，2025 年率先完成 FP4 浮点存内计算核心 IP 验证。"}],"investorsStructured":[{"name":"中兴通讯","role":"strategic","round":"天使轮","date":"2026-10","kind":"cvc","note":"战略投资，通信设备与算力服务器场景协同"},{"name":"博华产投","role":"follow","round":"天使轮","date":"2026-10","kind":"cvc"},{"name":"松青资本","role":"follow","round":"天使轮","date":"2026-10","kind":"vc"},{"name":"建信信托","role":"follow","round":"天使轮","date":"2026-10","kind":"pe"},{"name":"合创资本","role":"follow","round":"天使轮","date":"2026-10","kind":"vc"},{"name":"德同资本","role":"follow","round":"天使轮","date":"2026-10","kind":"vc","note":"老股东追投，同时参与种子轮"},{"name":"东方富海","role":"lead","round":"种子轮","date":"2026-05","kind":"vc","note":"联合领投"},{"name":"纪源资本","role":"lead","round":"种子轮","date":"2026-05","kind":"vc","note":"联合领投"},{"name":"徐汇资本","role":"follow","round":"种子轮","date":"2026-05","kind":"gov","note":"上海徐汇区国资背景"},{"name":"赛智伯乐","role":"follow","round":"种子轮","date":"2026-05","kind":"vc"}],"funding":[{"date":"2026-10","round":"天使轮","amount":"约亿元","inv":"战略投资：中兴通讯；联合投资：博华产投 / 松青资本 / 建信信托 / 合创资本；老股东追投：德同资本","investors":"中兴通讯（战略投资）· 博华产投 · 松青资本 · 建信信托 · 合创资本 · 德同资本（老股东追投）"},{"date":"2026-05","round":"种子轮","amount":"近亿元","inv":"领投：东方富海 / 纪源资本；跟投：徐汇资本 / 德同资本 / 赛智伯乐","investors":"东方富海（领投）· 纪源资本（领投）· 徐汇资本 · 德同资本 · 赛智伯乐"}],"note":"存算一体 AI 推理芯片国产替代对标：存算一体路线在能效上对标 Mythic（美国，模拟存内计算）、Syntiant（美国，端侧低功耗 NDP）、d-Matrix（美国，数字存内计算 + 3D 近存，主打数据中心推理）、Axelera AI（荷兰，数字 CIM）等国际厂商。思敏威是国内少数同时布局「3D 堆叠近存计算」与「SRAM 存内计算」双路线、并打通 FP4 浮点存内计算 IP 的团队，差异化在于以大模型推理为目标场景，用 3D 异质集成突破 SRAM-CIM 容量瓶颈。产业协同上已接入中兴通讯（战略股东，通信设备与算力服务器场景）与无问芯穹（推理引擎生态），并与领开半导体共同推进 HBF+ 高带宽闪存路线。风险在于存算一体的模拟精度一致性、编译器与工具链生态仍不成熟，且国内 CIM 赛道 C 轮之后融资断层，产业化节奏依赖大客户验证与流片窗口。"}'::jsonb)
ON CONFLICT (name) DO UPDATE SET
  code = EXCLUDED.code, industry = EXCLUDED.industry, seg = EXCLUDED.seg, listed = EXCLUDED.listed,
  round = EXCLUDED.round, cap = EXCLUDED.cap, valuation = EXCLUDED.valuation, rev = EXCLUDED.rev,
  last_funding = EXCLUDED.last_funding, data = EXCLUDED.data, updated_at = now();

